SPMission *Kashyyyk3BuildMission()
{
    return new Kashyyyk3Script();
}

Kashyyyk3Script::Kashyyyk3Script()
{
    int i, j, k, l, m, n;

    // Flat pointer arithmetic, not `m[j][i]`. `p + j*4 + i` reassociates as
    // (this + j*16) + i*4 with the member offset left in the store displacement;
    // `m[j][i]` folds the member offset into the index instead and costs 15 words.
    for (j = 0; j < 4; j++)
        for (i = 0; i < 4; i++)
            *((float *)mMatrixA.m + j * 4 + i) = 0.0f;
    for (l = 0; l < 4; l++)
        for (k = 0; k < 4; k++)
            *((float *)mMatrixB.m + l * 4 + k) = 0.0f;
    for (n = 0; n < 4; n++)
        for (m = 0; m < 4; m++)
            *((float *)mMatrixC.m + n * 4 + m) = 0.0f;

    mBoolCount = &mFlags[437] - (bool *)mPad24;
    mBools     = mFlags;
    mCountB    = (&mIntsB_[0] - (int *)&mFlags[439]) - 1;
    mIntsB     = mIntsB_;
    mCountC    = (&mHandles[554] - (int *)mPad478) - 1;
    mIntsC     = mHandles;
    mCountD    = (&mInts[33] - &mHandles[555]) - 1;
    mBlockD    = mInts;
}
